static int prepare_frame(char *output,size_t capacity,const char *request_digest){return snprintf(output,capacity,"format=darshan-recovery-target-native-authority-v2\nkind=ACQUIRE\noperation=PREPARE\ninstallation_id=20000000-0000-4000-8000-000000000002\nsite_id=fixture-site\nhost_installation_id=30000000-0000-4000-8000-000000000003\noperation_id=10000000-0000-4000-8000-000000000001\ngeneration=7\ntarget_set_id=%s\ntarget_handle=rtea:v1:target:abcdefghijklmnop\nprofile_sha256=%s\nenrollment_sha256=%s\nadmission_sha256=%s\nouter_envelope_sha256=%s\nrequest_sha256=%s\nauthorization_sha256=%s\ndeadline_unix_ms=2000000000000\nsupervisor_instance_sha256=%s\nsupervisor_generation=9\nreconciled_generation=9\nchallenge_nonce=11111111111111111111111111111111\n",d64,a64,d64,c64,c64,request_digest,b64,a64);}
