static int open_fixture(int root,const char *prefix,struct rtea_session *s,const char *frame,size_t frame_size,const char *wire,size_t wire_size,struct rtca_context *context,int *credentials,int *journal){char a[64],b[64];snprintf(a,sizeof(a),"%s-credentials",prefix);snprintf(b,sizeof(b),"%s-journal",prefix);*credentials=directory_at(root,a);*journal=directory_at(root,b);if(*credentials<0||*journal<0)return-1;return rtca_open_context(*credentials,*journal,s,frame,frame_size,wire,wire_size,now_ms(),context);}
static int file_identity(int directory,const char *name,ino_t *inode,off_t *size){int fd=openat(directory,name,O_RDONLY|O_CLOEXEC|O_NOFOLLOW);struct stat state;if(fd<0||fstat(fd,&state)<0){if(fd>=0)close(fd);return-1;}*inode=state.st_ino;*size=state.st_size;int result=(state.st_mode&0777)==0400&&state.st_nlink==1?0:-1;close(fd);return result;}
static int exact_inode_size(int directory,const char *name,ino_t *inode,off_t *size){struct stat state;if(fstatat(directory,name,&state,AT_SYMLINK_NOFOLLOW)<0||!S_ISREG(state.st_mode)||state.st_nlink!=1)return-1;*inode=state.st_ino;*size=state.st_size;return 0;}
static int scope_anchor_absent(int journal){int fd=openat(journal,"credential-provision.scope",O_RDONLY|O_CLOEXEC|O_NOFOLLOW);if(fd>=0){close(fd);return 0;}return errno==ENOENT;}
