static int replace_line_value(const char *input,size_t input_size,const char *key,const char *value,char *output,size_t capacity){size_t key_size=strlen(key),value_size=strlen(value);const char *start=strstr(input,key);if(!start||start[key_size]!='=')return-1;const char *old=start+key_size+1,*newline=memchr(old,'\n',input_size-(size_t)(old-input));if(!newline)return-1;size_t prefix=(size_t)(old-input),suffix=input_size-(size_t)(newline-input);if(prefix+value_size+suffix>capacity)return-1;memcpy(output,input,prefix);memcpy(output+prefix,value,value_size);memcpy(output+prefix+value_size,newline,suffix);return(int)(prefix+value_size+suffix);}
static int journal_has_no_secret_or_sentinel(int directory){int duplicate=dup(directory);DIR *scan=duplicate>=0?fdopendir(duplicate):NULL;if(!scan)return 0;struct dirent *entry;int ok=1;while((entry=readdir(scan))){if(entry->d_name[0]=='.'||!strcmp(entry->d_name,"credential-provision.scope"))continue;int fd=openat(directory,entry->d_name,O_RDONLY|O_CLOEXEC|O_NOFOLLOW);if(fd<0){ok=0;break;}char bytes[8192];ssize_t count=read(fd,bytes,sizeof(bytes)-1);close(fd);if(count<0){ok=0;break;}bytes[count]='\0';if(strstr(bytes,"RTCA_SECRET_SENTINEL")||strstr(bytes,"darshan_")||strstr(bytes,"password=")){ok=0;break;}}closedir(scan);return ok;}
